/**
 * Секреты не попадают в wrangler.jsonc и потому не приходят из `wrangler types`.
 * Объявляем их отдельно, дополняя сгенерированный интерфейс.
 *
 * Значение задаётся владельцем командой `wrangler secret put BOT_TOKEN`
 * и не хранится ни в репозитории, ни в конфигурации.
 */
interface Env {
  BOT_TOKEN: string
}
